              function saveNewSubCategory(catId) {
                  const name = document.getElementById('manageSubName').value.trim();
                  const order = parseInt(document.getElementById('manageSubOrder').value) || 1;
                  const image = document.getElementById('manageSubImage').value.trim();

                  if (!name) {
                      showToast("নাম অবশ্যই দিতে হবে!", "error");
                      return;
                  }

                  const cat = appCategories.find(c => c.id == catId);
                  if (cat) {
                      if(!cat.subCategories) cat.subCategories = [];
                      cat.subCategories.push({
                          id: Date.now(),
                          name: name,
                          order: order,
                          image: image || 'https://via.placeholder.com/150'
                      });
                      saveCategories();
                      const m = document.getElementById('categoryManageModal');
                      if(m) m.remove();

                      if (currentMenu === 'admin') {
                          const subView = document.querySelector('.admin-nav-item.active')?.getAttribute('data-view');
                          if (subView === 'all-products') renderAdminPostList();
                          else if (subView === 'categories') renderAdminCategoryList();
                          else renderProductList();
                      } else {
                          renderProductList();
                      }
                      showToast("সাব-ক্যাটাগরি যুক্ত হয়েছে", "success");
                  }
              }

              function deleteObjectFromCategory(catId, subId) {
                  if (!confirm('আপনি কি নিশ্চিত যে এটি ডিলিট করতে চান?')) return;

                  if (subId && subId !== 'null' && subId !== '') {
                      const cat = appCategories.find(c => c.id == catId);
                      cat.subCategories = cat.subCategories.filter(s => s.id != subId);
                  } else {
                      appCategories = appCategories.filter(c => c.id != catId);
                  }

                  saveCategories();
                  const m = document.getElementById('categoryManageModal');
                  if(m) m.remove();

                  if (currentMenu === 'admin') {
                      const subView = document.querySelector('.admin-nav-item.active')?.getAttribute('data-view');
                      if (subView === 'all-products') renderAdminPostList();
                      else if (subView === 'categories') renderAdminCategoryList();
                      else renderProductList();
                  } else {
                      renderProductList();
                  }
                  showToast("ডিলিট করা হয়েছে", "info");
              }

