              function syncManagerRecordsFromOrders() {
                  let changed = false;
                  (appOrders || []).forEach(o => {
                      if (o && (o.status === 'Delivered' || o.status === 'Confirmed' || o.status === 'Completed' || o.status === 'Delivery Completed')) {
                          const exists = appManagerRecords.some(r => String(r.order_id) === String(o.id));
                          if (!exists) {
                              // Compute Selling Price
                              let sellingPrice = Number(o.totalSellingPrice || o.total || 0);
                              let sellingPriceWarning = false;
                              if (isNaN(sellingPrice) || sellingPrice <= 0) {
                                  sellingPrice = 0;
                                  sellingPriceWarning = true;
                              }

                              // Compute Reseller Price
                              let resellerPrice = 0;
                              if (o.items && o.items.length > 0) {
                                  o.items.forEach(item => {
                                      const bPrice = Number(item.basePrice !== undefined ? item.basePrice : (item.price || 0));
                                      const qty = Number(item.qty || 1);
                                      resellerPrice += bPrice * qty;
                                  });
                              } else {
                                  resellerPrice = Number(o.totalBasePrice || 0);
                              }
                              
                              let resellerPriceWarning = false;
                              if (isNaN(resellerPrice) || resellerPrice <= 0) {
                                  resellerPrice = 0;
                                  resellerPriceWarning = true;
                              }

                              const profitAmount = Math.max(0, sellingPrice - resellerPrice);

                              const record = {
                                  id: 'MGR-' + o.id,
                                  order_id: o.id || 'N/A',
                                  token: o.paymentCode || o.secretToken || 'SEC-' + (Math.abs(Number(o.id) || Date.now()) % 900000 + 100000),
                                  reseller_id: o.profileId || 'N/A',
                                  reseller_name: o.resellerName || (o.shipping && o.shipping.name) || 'অজানা রিসেলার',
                                  customer_name: (o.shipping && o.shipping.name) || o.customerName || 'সম্মানিত কাস্টমার',
                                  selling_price: sellingPrice,
                                  reseller_price: resellerPrice,
                                  profit_amount: profitAmount,
                                  payment_status: 'Payment Pending',
                                  delivery_date: o.deliveryDate || new Date().toLocaleDateString('en-GB'),
                                  created_at: Date.now(),
                                  selling_price_warning: sellingPriceWarning,
                                  reseller_price_warning: resellerPriceWarning
                              };

                              appManagerRecords.push(record);
                              changed = true;
                              if (window.db) {
                                  window.db.collection('bexo_manager_records').doc(String(record.id)).set(sanitizeForFirestore(record))
                                      .catch(err => console.error("Firebase sync error:", err));
                              }
                          }
                      }
                  });
                  if (changed) {
                      saveManagerRecords();
                  }
              }

              function createOrUpdateManagerRecord(order) {
                  if (!order) return;
                  const existingIdx = appManagerRecords.findIndex(r => String(r.order_id) === String(order.id));
                  
                  let sellingPrice = Number(order.totalSellingPrice || order.total || 0);
                  let sellingPriceWarning = false;
                  if (isNaN(sellingPrice) || sellingPrice <= 0) {
                      sellingPrice = 0;
                      sellingPriceWarning = true;
                  }

                  let resellerPrice = 0;
                  if (order.items && order.items.length > 0) {
                      order.items.forEach(item => {
                          const bPrice = Number(item.basePrice !== undefined ? item.basePrice : (item.price || 0));
                          const qty = Number(item.qty || 1);
                          resellerPrice += bPrice * qty;
                      });
                  } else {
                      resellerPrice = Number(order.totalBasePrice || 0);
                  }

                  let resellerPriceWarning = false;
                  if (isNaN(resellerPrice) || resellerPrice <= 0) {
                      resellerPrice = 0;
                      resellerPriceWarning = true;
                  }

                  const profitAmount = Math.max(0, sellingPrice - resellerPrice);

                  const record = {
                      id: existingIdx > -1 ? appManagerRecords[existingIdx].id : 'MGR-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
                      order_id: order.id || 'N/A',
                      token: order.paymentCode || order.secretToken || 'SEC-' + (Math.abs(Number(order.id) || Date.now()) % 900000 + 100000),
                      reseller_id: order.profileId || 'N/A',
                      reseller_name: order.resellerName || (order.shipping && order.shipping.name) || 'অজানা রিসেলার',
                      customer_name: (order.shipping && order.shipping.name) || order.customerName || 'সম্মানিত কাস্টমার',
                      selling_price: sellingPrice,
                      reseller_price: resellerPrice,
                      profit_amount: profitAmount,
                      payment_status: existingIdx > -1 ? appManagerRecords[existingIdx].payment_status : 'Payment Pending',
                      delivery_date: order.deliveryDate || new Date().toLocaleDateString('en-GB'),
                      created_at: existingIdx > -1 ? appManagerRecords[existingIdx].created_at : Date.now(),
                      selling_price_warning: sellingPriceWarning,
                      reseller_price_warning: resellerPriceWarning
                  };

                  if (existingIdx > -1) {
                      appManagerRecords[existingIdx] = record;
                  } else {
                      appManagerRecords.unshift(record);
                  }

                  saveManagerRecords();

                  if (window.db) {
                      window.db.collection('bexo_manager_records').doc(String(record.id)).set(sanitizeForFirestore(record))
                          .catch(err => console.error("Firebase sync error:", err));
                  }

                  if (resellerPriceWarning) {
                      showToast("রিসেলার প্রাইস মিসিং! পণ্যটির প্রাইস আপডেট করুন।", "error");
                  } else if (sellingPriceWarning) {
                      showToast("সেলিং প্রাইস মিসিং! সেলিং প্রাইস ০ ধরা হয়েছে।", "warning");
                  }
              }

