              function handleBalanceStatement() {
                  const main = document.getElementById('mainContent');
                  const history = [...userProfile.rechargeTransactions].reverse();

                  main.innerHTML = `
                      <div class="p-6 bg-[#f3f4f9] min-h-screen animate-fade-in font-sans">
                          <div class="max-w-4xl mx-auto space-y-6">
                              <div class="flex items-center justify-between">
                                  <div>
                                      <h2 class="text-2xl font-black text-slate-800">ব্যালেন্স স্টেটমেন্ট</h2>
                                      <p class="text-slate-400 text-[10px] font-bold uppercase tracking-widest">আপনার সকল লেনদেনের বিস্তারিত তালিকা</p>
                                  </div>
                                  <button onclick="renderRechargeDashboard()" class="px-4 py-2 bg-white rounded-lg font-bold text-xs hover:bg-slate-50 transition-all cursor-pointer"><i class="fas fa-arrow-left mr-2"></i>ব্যাক</button>
                              </div>

                              <div class="space-y-3">
                                  ${history.length === 0 ? `
                                      <div class="bg-white p-20 rounded-3xl text-center border border-dashed border-slate-200">
                                          <i class="fas fa-receipt text-4xl text-slate-100 mb-4"></i>
                                          <p class="text-slate-400 text-xs font-black uppercase tracking-widest">কোনো লেনদেন পাওয়া যায়নি</p>
                                      </div>
                                  ` : history.map(t => {
                                      const isPlus = t.type === 'Add Balance';
                                      const statusText = t.status ? String(t.status).toLowerCase() : 'pending';
                                      const isSuccess = ['completed', 'approved', 'successful'].includes(statusText);
                                      const isFailed = ['rejected', 'failed'].includes(statusText);
                                      
                                      let badgeColor = 'bg-orange-50 text-orange-600 border border-orange-100';
                                      if (isSuccess) badgeColor = 'bg-emerald-50 text-emerald-600 border border-emerald-100';
                                      if (isFailed) badgeColor = 'bg-rose-50 text-rose-600 border border-rose-100';

                                      return `
                                      <div class="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center justify-between hover:shadow-md transition-all animate-fade-in">
                                          <div class="flex items-center gap-4">
                                              <div class="w-12 h-12 ${t.type === 'Recharge' ? 'bg-blue-50 text-blue-500' : t.type === 'Bill Pay' ? 'bg-amber-50 text-amber-600' : t.type === 'Order Advance' ? 'bg-rose-50 text-rose-500' : 'bg-emerald-50 text-emerald-600'} rounded-xl flex items-center justify-center text-xl">
                                                  <i class="fas ${t.type === 'Recharge' ? 'fa-mobile-alt' : t.type === 'Bill Pay' ? 'fa-bolt' : t.type === 'Order Advance' ? 'fa-shopping-cart' : 'fa-plus-circle'}"></i>
                                              </div>
                                              <div>
                                                  <div class="flex items-center gap-2">
                                                      <h4 class="text-sm font-black text-slate-800">${t.type === 'Bill Pay' ? t.billName : t.type}</h4>
                                                      <span class="px-2 py-0.5 rounded text-[9px] font-black uppercase tracking-tighter ${badgeColor}">${t.status || 'PENDING'}</span>
                                                  </div>
                                                  <p class="text-[10px] font-bold text-slate-400">${t.time || 'N/A'} • ${t.number || t.accountId || 'ID: ' + (t.id || 'N/A')}</p>
                                                  ${t.trxId ? `<p class="text-[10px] text-emerald-600 font-bold mt-1 inline-flex items-center gap-1 font-mono"><i class="fas fa-check-circle"></i> TrxID: ${t.trxId}</p>` : ''}
                                                  ${t.adminNote ? `<p class="text-[10px] text-slate-500 font-medium italic mt-0.5 pl-2 border-l-2 border-slate-200">নোট: ${t.adminNote}</p>` : ''}
                                              </div>
                                          </div>
                                          <div class="text-right">
                                              <p class="text-base font-black ${isPlus ? 'text-emerald-600' : 'text-rose-600'}">${isPlus ? '+' : '-'} ৳${t.amount}</p>
                                              <p class="text-[10px] font-black text-slate-300">REF: ${t.id || 'N/A'}</p>
                                          </div>
                                      </div>
                                  `;}).join('')}
                              </div>
                          </div>
                      </div>
                  `;
              }


              function renderProductList(selectedCategory = null, selectedSubCategory = null) {
                  const main = document.getElementById('mainContent');

                  if (selectedCategory || selectedSubCategory) {
                      renderFilteredProductList(selectedCategory, selectedSubCategory);
                      return;
                  }

                  // Get product counts
                  const counts = {};
                  const subImages = {};
                  appPosts.forEach(p => {
                      const c = p.category || 'অন্যান্য';
                      const s = p.subCategory || 'অন্যান্য';
                      if (!counts[c]) counts[c] = { total: 0, subs: {} };
                      if (!counts[c].subs[s]) {
                          counts[c].subs[s] = 0;
                          subImages[`${c}_${s}`] = (p.images && p.images.length > 0) ? p.images[0] : 'https://via.placeholder.com/150';
                      }
                      counts[c].subs[s]++;
                      counts[c].total++;
                  });

                  const adminMode = isUserAdmin();
                  const catsHtml = (appCategories || []).sort((a,b) => (a.order || 0) - (b.order || 0)).map(cat => {
                      const totalInCat = counts[cat.name]?.total || 0;

                      const subsHtml = (cat.subCategories || []).sort((a,b) => (a.order || 0) - (b.order || 0)).map(sub => {
                          const count = counts[cat.name]?.subs[sub.name] || 0;
                          const image = subImages[`${cat.name}_${sub.name}`] || sub.image;

                          return `
                              <div onclick="renderProductList('${cat.name}', '${sub.name}')" class="bg-white rounded-lg border border-slate-50 flex flex-col items-center justify-between p-2 shadow-sm transition-all hover:shadow-md cursor-pointer relative group">
                                  <div class="absolute top-1 right-1 bg-slate-50 text-[8px] font-black text-slate-300 px-1.5 py-0.5 rounded-full z-10 transition-colors group-hover:bg-orange-100 group-hover:text-orange-600">${count}</div>
                                  <div class="w-20 h-20 flex items-center justify-center p-1.5">
                                      <img src="${image}" alt="${sub.name}" class="max-w-full max-h-full object-contain transition-transform group-hover:scale-110 duration-500">
                                  </div>
                                  <div class="mt-1 text-center w-full">
                                      <p class="text-[9px] font-black text-slate-500 truncate translate-y-0.5 transition-colors group-hover:text-pink-600">${sub.name}</p>
                                  </div>
                              </div>
                          `;
                      }).join('');

                      return `
                          <div class="space-y-4 animate-fade-in">
                              <div class="bg-white/60 py-2.5 px-4 rounded-xl text-center border border-white/40 shadow-sm backdrop-blur-sm">
                                  <h3 class="text-[13px] font-black text-pink-600 tracking-tight">${cat.name} (${totalInCat})</h3>
                              </div>
                              <div class="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-2 md:gap-3">
                                  ${subsHtml}
                              </div>
                          </div>
                      `;
                  }).join('');

                  main.innerHTML = `
                      <div class="p-4 lg:p-8 animate-fade-in bg-[#f4f7fa] min-h-screen">
                          <div class="max-w-7xl mx-auto space-y-12 pb-20">
                              ${catsHtml || `
                                  <div class="flex flex-col items-center justify-center py-20 text-center space-y-4">
                                      <div class="w-20 h-20 bg-white rounded-full flex items-center justify-center text-slate-200 text-3xl shadow-sm border border-slate-50">
                                          <i class="fas fa-box-open"></i>
                                      </div>
                                      <h3 class="font-black text-slate-400 uppercase tracking-widest text-xs">কোন ক্যাটাগরি পাওয়া যায়নি</h3>
                                  </div>
                              `}
                          </div>
                      </div>
                  `;
              }

              function renderFilteredProductList(category, subCategory) {
                  const main = document.getElementById('mainContent');

                  // Filter products
                  const filtered = appPosts.filter(p => {
                      const isPublished = p.isPublished !== false;
                      if (!isPublished) return false;

                      if (category && subCategory) return p.category === category && p.subCategory === subCategory;
                      if (category) return p.category === category;
                      if (subCategory) return p.subCategory === subCategory;
                      return true;
                  }).sort((a, b) => Number(b.id) - Number(a.id));

                  // Flatten products for image-based view
                  const allFlattened = [];
                  filtered.forEach(p => {
                      p.images.forEach((img, idx) => {
                          allFlattened.push({
                              postId: p.id,
                              image: img,
                              title: p.title,
                              price: p.price,
                              author: p.author,
                              imgIdx: idx
                          });
                      });
                  });

                  const totalPages = Math.ceil(allFlattened.length / productsPerPage);
                  if (productCurrentPage > totalPages) productCurrentPage = 1;
                  const start = (productCurrentPage - 1) * productsPerPage;
                  const paginated = allFlattened.slice(start, start + productsPerPage);

                  main.innerHTML = `
                      <div class="p-2 lg:p-6 animate-fade-in bg-[#f0f4f9] min-h-screen">
                          <div class="max-w-full mx-auto space-y-4">
                              <div class="bg-white p-4 rounded-xl shadow-sm border border-slate-100 flex items-center justify-between">
                                  <div class="flex items-center gap-4">
                                      <button onclick="renderProductList()" class="w-9 h-9 bg-slate-50 text-slate-400 rounded-lg flex items-center justify-center hover:bg-orange-50 hover:text-orange-600 transition-all border border-slate-100">
                                          <i class="fas fa-chevron-left text-sm"></i>
                                      </button>
                                      <div>
                                          <h2 class="text-xl font-black text-slate-800 tracking-tight">${subCategory || category || 'সকল প্রোডাক্ট'}</h2>
                                          <p class="text-slate-400 text-[10px] font-bold">বেক্সো বিডি-র সকল লেটেস্ট কালেকশন এখানে পাবেন</p>
                                      </div>
                                  </div>

                                  <div class="w-10 h-10 bg-orange-600 text-white rounded-lg flex items-center justify-center text-lg shadow-lg shadow-orange-100">
                                      <i class="fas fa-th"></i>
                                  </div>
                              </div>

                              <div id="productGrid" class="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-2 lg:gap-3">
                                  ${paginated.map(p => {
                                      const postObj = appPosts.find(item => String(item.id) === String(p.postId));
                                      return postObj ? renderPostCard(postObj, p.imgIdx, false) : '';
                                  }).join('')}
                              </div>

                              <div id="productPagination" class="flex flex-col items-center gap-4 py-8"></div>
                          </div>
                      </div>
                  `;
                  renderPagination('productPagination', totalPages, () => renderFilteredProductList(category, subCategory));
              }

              // Fix renderPagination to support function callback
              function renderPagination(containerId, totalPages, callback) {
                  const container = document.getElementById(containerId);
                  if (!container) return;
                  if (totalPages <= 1) {
                      container.innerHTML = `<p class="text-slate-400 text-[10px] font-bold mt-4">Page 1 of 1</p>`;
                      return;
                  }

                  // If callback is a string, we call changePage, if it's a function we wrap it
                  const pageChangeHandler = (delta) => {
                      const newPage = productCurrentPage + delta;
                      if (newPage < 1 || newPage > totalPages) return;
                      productCurrentPage = newPage;
                      if (typeof callback === 'function') {
                          callback();
                      } else if (typeof window[callback] === 'function') {
                          window[callback]();
                      }
                  };

                  // Inject the handler globally to be called from onclick
                  window.temp_pagination_callback = pageChangeHandler;

                  container.innerHTML = `
                      <div class="flex items-center gap-2">
                          <button onclick="temp_pagination_callback(-1)"
                                  class="bg-[#79c68a] text-white px-4 py-2 rounded font-bold text-sm flex items-center gap-2 shadow-sm shadow-emerald-100 transition-all ${productCurrentPage === 1 ? 'opacity-50 cursor-not-allowed' : 'hover:bg-emerald-600'}">
                              <i class="fas fa-angle-double-left"></i> Prev
                          </button>
                          <button onclick="temp_pagination_callback(1)"
                                  class="bg-[#79c68a] text-white px-4 py-2 rounded font-bold text-sm flex items-center gap-2 shadow-sm shadow-emerald-100 transition-all ${productCurrentPage === totalPages ? 'opacity-50 cursor-not-allowed' : 'hover:bg-emerald-600'}">
                              Next <i class="fas fa-angle-double-right"></i>
                          </button>
                      </div>
                      <p class="text-slate-400 text-[11px] font-bold mt-2">Page ${productCurrentPage} of ${totalPages}</p>
                  `;
              }

              function renderFavorites() {
                  const main = document.getElementById('mainContent');
                  main.innerHTML = `
                      <div class="p-2 lg:p-6 animate-fade-in bg-[#f0f4f9] min-h-screen">
                          <div class="max-w-full mx-auto space-y-4">
                              <div class="bg-white p-4 rounded-xl shadow-sm border border-slate-100 flex items-center justify-between">
                                  <div>
                                      <h2 class="text-xl font-black text-slate-800 tracking-tight">ফেভারিট প্রোডাক্ট</h2>
                                      <p class="text-slate-400 text-[10px] font-bold">আপনার পছন্দের সকল প্রোডাক্ট এখানে আলাদাভাবে রয়েছে</p>
                                  </div>
                                  <div class="w-10 h-10 bg-rose-600 text-white rounded-lg flex items-center justify-center text-lg shadow-lg shadow-rose-100">
                                      <i class="fas fa-heart"></i>
                                  </div>
                              </div>

                              <div id="favoriteFeed" class="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-2 lg:gap-3"></div>
                              <div id="favoritePagination" class="flex flex-col items-center gap-4 py-8"></div>
                          </div>
                      </div>
                  `;

                  const feed = document.getElementById('favoriteFeed');

                  const flattenedFavs = [];
                  appPosts.forEach(p => {
                      p.images.forEach((img, idx) => {
                          const key = `${p.id}-${idx}`;
                          if (userProfile.favorites && userProfile.favorites.includes(key)) {
                              flattenedFavs.push({
                                  postId: p.id,
                                  image: img,
                                  title: p.title,
                                  price: p.price,
                                  imgIdx: idx
                              });
                          }
                      });
                  });

                  if (flattenedFavs.length === 0) {
                      feed.className = "flex items-center justify-center w-full col-span-full py-20";
                      feed.innerHTML = `
                          <div class="text-center bg-white p-12 rounded-[2rem] border border-slate-100 shadow-xl shadow-slate-100 max-w-md w-full">
                              <div class="w-20 h-20 bg-rose-50 text-rose-200 rounded-full flex items-center justify-center mx-auto text-3xl mb-4">
                                  <i class="fas fa-heart"></i>
                              </div>
                              <h3 class="text-lg font-bold text-slate-800">কোনো ফেভারিট প্রোডাক্ট নেই</h3>
                              <p class="text-[10px] text-slate-500 mt-1">প্রোডাক্ট লিস্ট থেকে আপনার পছন্দের প্রোডাক্ট ফেভারিট করুন।</p>
                          </div>
                      `;
                      return;
                  }

                  const totalPages = Math.ceil(flattenedFavs.length / productsPerPage);
                  if (productCurrentPage > totalPages) productCurrentPage = 1;
                  const start = (productCurrentPage - 1) * productsPerPage;
                  const paginated = flattenedFavs.slice(start, start + productsPerPage);

                  feed.innerHTML = paginated.map(p => {
                      const postObj = appPosts.find(item => String(item.id) === String(p.postId));
                      return postObj ? renderPostCard(postObj, p.imgIdx, false) : '';
                  }).join('');

                  renderPagination('favoritePagination', totalPages, 'renderFavorites');
              }

