              function submitPremiumRequest() {
                  const method = document.getElementById('premMethod').value;
                  const profileId = document.getElementById('premProfileId').value;
                  const trxId = document.getElementById('premTrxId').value;
                  const lastDigits = document.getElementById('premLastDigits').value;

                  if(!trxId || !lastDigits) {
                      alert("দয়া করে পেমেন্টের সব তথ্য প্রদান করুন!");
                      return;
                  }

                  const request = {
                      id: Date.now(),
                      profileId,
                      method,
                      trxId,
                      lastDigits,
                      status: 'pending',
                      time: new Date().toLocaleString()
                  };

                  appPremiumRequests.unshift(request);
                  savePremiumRequests();

                  alert("আপনার রিকোয়েস্টটি সাবমিট হয়েছে। এডমিন ভেরিফাই করার পর আপনার সার্ভিসটি একটিভ হবে।");
                  switchMenu('videos');
              }

              function copyToClipboard(text) {
                  navigator.clipboard.writeText(text).then(() => {
                      alert("নম্বরটি কপি করা হয়েছে: " + text);
                  }).catch(err => {
                      console.error('Could not copy text: ', err);
                      const textArea = document.createElement("textarea");
                      textArea.value = text;
                      document.body.appendChild(textArea);
                      textArea.select();
                      try {
                          document.execCommand('copy');
                          alert("নম্বরটি কপি করা হয়েছে: " + text);
                      } catch (err) {
                          alert("কপি করা সম্ভব হয়নি। ম্যানুয়ালি টাইপ করুন।");
                      }
                      document.body.removeChild(textArea);
                  });
              }

              function countProductsInCategory(catName) {
                  return appPosts.filter(p => p.category === catName).length;
              }

              function countProductsInSub(subName) {
                  return appPosts.filter(p => p.subCategory === subName).length;
              }

              function filterBySub(catName, subName) {
                  filterMain = catName;
                  filterSub = subName;
                  switchMenu('dashboard');
              }

