              function updateProfile() {
                  try {
                      // Get fresh values from inputs
                      const phone = document.getElementById('profilePhone').value.trim();
                      const name = document.getElementById('profileName').value.trim();
                      const shop = document.getElementById('profileShop').value.trim();
                      const email = document.getElementById('profileEmail').value.trim();
                      const fbPage = document.getElementById('profileFbPage').value.trim();
                      const website = document.getElementById('profileWebsite').value.trim();
                      const district = document.getElementById('profileDistrict').value.trim();
                      const address = document.getElementById('profileAddress').value.trim();

                      // Basic Validation
                      if(!phone || !name || !shop || !district || !address) {
                          showToast("সব বাধ্যতামুলক তথ্য প্রদান করুন।", "error");
                          return;
                      }

                      // Update the state object
                      userProfile.phone = phone;
                      userProfile.fullName = name;
                      userProfile.shopName = shop;
                      userProfile.email = email;
                      userProfile.fbPage = fbPage;
                      userProfile.website = website;
                      userProfile.district = district;
                      userProfile.address = address;

                      // Persist
                      saveProfile();

                      // Refresh UI
                      renderProfile();

                      // Show success notification - prominent
                      showToast("✅ প্রোফাইল সফলভাবে আপডেট হয়েছে!", "success");

                      // Scroll to top to show confirmation
                      const mainWrapper = document.getElementById('mainWrapper');
                      if(mainWrapper) mainWrapper.scrollTo({ top: 0, behavior: 'smooth' });

                      // Explicitly show the inline alert
                      const alertBox = document.getElementById('profileAlert');
                      if(alertBox) {
                          alertBox.innerHTML = `
                              <div class="flex items-center gap-3">
                                  <i class="fas fa-check-circle text-2xl"></i>
                                  <div>
                                      <p class="font-black">অভিনন্দন!</p>
                                      <p class="text-xs font-bold opacity-90">আপনার প্রোফাইল তথ্য সফলভাবে সংরক্ষিত হয়েছে।</p>
                                  </div>
                              </div>
                          `;
                          alertBox.classList.remove('hidden');
                          alertBox.classList.add('animate-bounce-in');
                          setTimeout(() => {
                              if(alertBox) {
                                  alertBox.classList.remove('animate-bounce-in');
                                  alertBox.classList.add('animate-fade-out');
                                  setTimeout(() => alertBox.classList.add('hidden'), 500);
                              }
                          }, 6000);
                      }

                  } catch (error) {
                      console.error("Profile Update Error:", error);
                      showToast("প্রোফাইল আপডেট করতে সমস্যা হয়েছে।", "error");
                  }
              }

              function triggerAvatarUpload() {
                  const fileInput = document.getElementById('avatarInput');
                  if (fileInput) fileInput.click();
              }
              window.triggerAvatarUpload = triggerAvatarUpload;

              function handleAvatarFileSelect(event) {
                  const file = event.target.files[0];
                  if (!file) return;

                  if (!file.type.startsWith('image/')) {
                      showToast("অনুগ্রহ করে একটি ছবি নির্বাচন করুন।", "error");
                      return;
                  }

                  const reader = new FileReader();
                  reader.onload = function(e) {
                      const img = new Image();
                      img.onload = function() {
                          const canvas = document.createElement('canvas');
                          const MAX_WIDTH = 250;
                          const MAX_HEIGHT = 250;
                          let width = img.width;
                          let height = img.height;

                          if (width > height) {
                              if (width > MAX_WIDTH) {
                                  height *= MAX_WIDTH / width;
                                  width = MAX_WIDTH;
                              }
                          } else {
                              if (height > MAX_HEIGHT) {
                                  width *= MAX_HEIGHT / height;
                                  height = MAX_HEIGHT;
                              }
                          }

                          canvas.width = width;
                          canvas.height = height;
                          const ctx = canvas.getContext('2d');
                          ctx.drawImage(img, 0, 0, width, height);

                          const dataUrl = canvas.toDataURL('image/jpeg', 0.84);
                          userProfile.avatar = dataUrl;
                          saveProfile();
                          updateHeaderUI();
                          renderProfile();
                          showToast("প্রোফাইল ছবি সফলভাবে আপলোড হয়েছে!", "success");
                      };
                      img.src = e.target.result;
                  };
                  reader.readAsDataURL(file);
              }
              window.handleAvatarFileSelect = handleAvatarFileSelect;

