              function saveAdminNewUser() {
                  const shop = document.getElementById('adminNewUserShop').value.trim();
                  const name = document.getElementById('adminNewUserName').value.trim();
                  const phone = document.getElementById('adminNewUserPhone').value.trim();
                  const pass = document.getElementById('adminNewUserPass').value;
                  const email = document.getElementById('adminNewUserEmail').value.trim();
                  const addr = document.getElementById('adminNewUserAddress').value.trim();
                  const district = document.getElementById('adminNewUserDistrict').value.trim();
                  const refCode = document.getElementById('adminNewUserReferral').value.trim();
                  const balance = Number(document.getElementById('adminNewUserBalance').value) || 0;
                  const plan = document.getElementById('adminNewUserPlan').value;
                  const isPremium = document.getElementById('adminNewUserPrem').checked;
                  const hasWebsite = document.getElementById('adminNewUserWeb').checked;

                  if (!shop || !name || !phone || !pass || !addr) {
                      showToast("স্টার চিহ্নিত প্রতিটি ঘর পূরণ করা বাধ্যতামূলক!", "error");
                      return;
                  }

                  if (pass.length < 6) {
                      showToast("পাসওয়ার্ড কমপক্ষে ৬ অক্ষরের হতে হবে!", "error");
                      return;
                  }

                  // Normalized Phone match check
                  const normalizedNewPhone = normalizePhone(phone);
                  const existing = appUsers.find(u => normalizePhone(u.phone) === normalizedNewPhone);
                  if (existing) {
                      showToast("এই ফোন নম্বর দিয়ে ইতিপূর্বে অ্যাকাউন্ট খোলা হয়েছে!", "error");
                      return;
                  }

                  // Passive Income Referral checking
                  let referredBy = null;
                  if (refCode) {
                      const r = findReferrerByCode(refCode);
                      if (r) {
                          referredBy = r.profileId;
                      } else {
                          showToast("ভুল রেফারেল বা সেলার কোড!", "error");
                          return;
                      }
                  }

                  const profileId = 'BX-' + Math.floor(100000 + Math.random() * 900000);

                  const newUser = {
                      ...DEFAULT_PROFILE,
                      profileId: profileId,
                      shopName: shop,
                      fullName: name,
                      phone: phone,
                      email: email,
                      address: addr,
                      district: district,
                      password: pass,
                      referredBy: referredBy,
                      rechargeBalance: balance,
                      currentPlan: plan,
                      isPremium: isPremium,
                      hasWebsite: hasWebsite,
                      joinDate: new Date().toLocaleDateString('bn-BD'),
                      createdAt: Date.now(),
                      lastActive: 'Never'
                  };

                  appUsers.push(newUser);
                  saveUsers(profileId);

                  // Referral Commission Bonus logic
                  if (referredBy) {
                      const refs = JSON.parse(localStorage.getItem('bexo_referrals')) || [];
                      refs.push({
                          referredBy: refCode,
                          name: shop,
                          commission: 50,
                          date: new Date().toLocaleString()
                      });
                      localStorage.setItem('bexo_referrals', JSON.stringify(refs));
                  }

                  const m = document.getElementById('adminCreateUserModal');
                  if (m) m.remove();

                  showToast("নতুন ইউজার তৈরি সফল হয়েছে!", "success");
                  renderAdminUsers();
              }

              function filterAdminUsers(val) {
                  const cleanVal = convertBanglaToEnglishDigits(val).toLowerCase().trim();
                  const tbody = document.getElementById('adminUserTableBody');
                  if (!tbody) return;

                  if (!cleanVal) {
                      tbody.innerHTML = renderAdminUserRows(appUsers);
                      return;
                  }

                  const filtered = appUsers.filter(u => {
                      const name = (u.fullName || '').toLowerCase();
                      const id = (u.profileId || '').toLowerCase();
                      const phone = (u.phone || '').toLowerCase();
                      const shopName = (u.shopName || '').toLowerCase();
                      return name.includes(cleanVal) || id.includes(cleanVal) || phone.includes(cleanVal) || shopName.includes(cleanVal);
                  });

                  tbody.innerHTML = renderAdminUserRows(filtered);
              }

              function renderAdminUserRows(users) {
                  const sortedUsers = (users || []).slice().sort((a, b) => {
                      const cA = Number(a.createdAt) || 0;
                      const cB = Number(b.createdAt) || 0;
                      if (cA !== cB) return cB - cA;

                      const dA = a.joinDate ? (getDateOfRecord(a.joinDate)?.getTime() || 0) : 0;
                      const dB = b.joinDate ? (getDateOfRecord(b.joinDate)?.getTime() || 0) : 0;
                      if (dA !== dB) return dB - dA;

                      const numA = Number(String(a.profileId).replace(/\D/g, '')) || 0;
                      const numB = Number(String(b.profileId).replace(/\D/g, '')) || 0;
                      return numB - numA;
                  });

                  return sortedUsers.map(u => {
                      const balance = Number(u.rechargeBalance !== undefined ? u.rechargeBalance : u.balance) || 0;
                      const profit = Number(u.salesProfit) || 0;
                      const totalOrders = Number(u.orders) || 0;

                      return `
                          <tr class="border-b border-slate-50 hover:bg-slate-50/80 transition-all group">
                              <td class="px-8 py-6">
                                  <div class="flex items-center gap-4">
                                      <div class="w-12 h-12 bg-white border border-slate-100 rounded-2xl shadow-sm flex items-center justify-center font-black text-orange-600 transition-transform group-hover:scale-110">${(u.fullName || 'User')[0]}</div>
                                      <div>
                                          <p class="text-sm font-black text-slate-800">${u.fullName || 'Unknown'}</p>
                                          <p class="text-[10px] text-slate-400 font-mono font-bold tracking-tighter">${u.profileId} <span class="mx-1">•</span> ${u.phone || 'N/A'}</p>
                                      </div>
                                  </div>
                              </td>
                              <td class="px-8 py-6">
                                  <div class="flex flex-wrap gap-1.5">
                                      <button onclick="toggleUserBadge('${u.profileId}', 'isPremium')" class="px-3 py-1 rounded-lg text-[9px] font-black tracking-widest ${u.isPremium ? 'bg-orange-600 text-white shadow-sm' : 'bg-slate-100 text-slate-500 border border-slate-200'}">PRM</button>
                                      <button onclick="toggleUserBadge('${u.profileId}', 'hasWebsite')" class="px-3 py-1 rounded-lg text-[9px] font-black tracking-widest ${u.hasWebsite ? 'bg-indigo-600 text-white shadow-sm' : 'bg-slate-100 text-slate-500 border border-slate-200'}">WEB</button>
                                      <button onclick="toggleUserBadge('${u.profileId}', 'isSubscribed')" class="px-3 py-1 rounded-lg text-[9px] font-black tracking-widest ${u.isSubscribed ? 'bg-emerald-600 text-white shadow-sm' : 'bg-slate-100 text-slate-500 border border-slate-200'}">SUB</button>
                                  </div>
                              </td>
                              <td class="px-8 py-6">
                                  <p class="text-sm font-black text-emerald-600">৳ ${balance.toLocaleString()}</p>
                                  <p class="text-[9px] text-slate-400 font-bold uppercase tracking-widest">কারেন্ট ব্যালেন্স</p>
                              </td>
                              <td class="px-8 py-6">
                                  <div class="flex items-center gap-2">
                                      <span class="w-2 h-2 rounded-full bg-blue-500"></span>
                                      <p class="text-sm font-black text-slate-700">৳ ${profit.toLocaleString()}</p>
                                  </div>
                                  <p class="text-[9px] text-slate-400 font-bold uppercase tracking-widest">${totalOrders} টি অর্ডার</p>
                              </td>
                              <td class="px-8 py-6">
                                  ${(() => {
                                      if(!u.lastActive || u.lastActive === 'Never') return '<span class="text-[9px] font-bold text-slate-300">Never</span>';
                                      const date = new Date(u.lastActive);
                                      const now = new Date();
                                      const diff = now - date;
                                      if(diff < 5 * 60 * 1000) return '<span class="flex items-center gap-1.5 text-[9px] font-black text-emerald-500 uppercase"><span class="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></span> Online</span>';
                                      return `<span class="text-[9px] font-bold text-slate-400 whitespace-nowrap">${date.toLocaleString('bn-BD', {hour:'2-digit', minute:'2-digit'})}</span>`;
                                  })()}
                              </td>
                              <td class="px-8 py-6 text-right flex items-center justify-end gap-2">
                                  <button onclick="viewUserProfileInAdmin('${u.profileId}')" class="px-4 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase tracking-widest hover:bg-orange-600 transition-colors shadow-sm">
                                      প্রোফাইল
                                  </button>
                                  <button onclick="adminToggleUserBan('${u.profileId}')" class="w-8 h-8 rounded-lg border border-slate-100 flex items-center justify-center transition-all ${typeof isUserBanned === 'function' && isUserBanned(u.profileId) ? 'bg-rose-600 text-white border-rose-600' : 'bg-white text-slate-400 hover:bg-rose-50 hover:text-rose-600'}">
                                      <i class="fas fa-ban text-[10px]"></i>
                                  </button>
                              </td>
                          </tr>
                      `;
                  }).reverse().join('');
              }

              function toggleUserBadge(profileId, field) {
                  const idx = appUsers.findIndex(u => u.profileId === profileId);
                  if (idx > -1) {
                      appUsers[idx][field] = !appUsers[idx][field];
                      saveUsers(profileId);
                      if (profileId === userProfile.profileId) {
                          userProfile[field] = appUsers[idx][field];
                          saveProfile();
                          updateHeaderUI();
                      }
                      renderAdminUsers();
                      showToast(`ইউজার বেজ আপডেট করা হয়েছে।`, 'success');
                  }
              }

