                // Global helper routines for settlement dash
                window.deleteAllSettlementAuditLogs = async function() {
                    const settlements = appTransactions.filter(t => t.type === 'Reseller Settlement');
                    if (settlements.length === 0) {
                        showToast("ডিলিট করার মতো কোনো সেটেলমেন্ট রেকর্ড পাওয়া যায়নি!", "info");
                        return;
                    }

                    if (!confirm(`আপনি কি নিশ্চিত যে আপনি সকল ${settlements.length}টি নিষ্পত্তির রেকর্ড এবং প্রফিট অডিট ট্রেইল ডিলিট করতে চান?\nএটি ডাটাবেস থেকে স্থায়ীভাবে মুছে যাবে!`)) {
                        return;
                    }

                    const resetOrders = confirm("রেকর্ড ডিলিট করার পাশাপাশি কি সম্পৃক্ত অর্ডারগুলোর 'নিষ্পত্তি স্ট্যাটাস' রিসেট করতে চান? (যাতে পুনরায় সেটেলমেন্ট করা যায়)");

                    showToast("সেটেলমেন্ট রেকর্ড ডিলিট করা হচ্ছে...", "info");

                    try {
                        let deletePromises = [];
                        let orderResetPromises = [];

                        // 1. Delete transactions from Firestore bexo_transactions
                        if (window.db) {
                            settlements.forEach(t => {
                                if (t.id) {
                                    deletePromises.push(
                                        window.db.collection('bexo_transactions').doc(String(t.id)).delete()
                                            .catch(err => console.error(`Error deleting doc ${t.id}:`, err))
                                    );
                                }
                            });
                        }

                        // 2. Reset orders isProfitDistributed
                        if (resetOrders) {
                            const settledOrderNos = settlements.map(t => String(t.orderNo || t.id));
                            appOrders.forEach(o => {
                                const match = settledOrderNos.includes(String(o.orderNo || o.id)) || o.isProfitDistributed;
                                if (match) {
                                    o.isProfitDistributed = false;
                                    if ('settlementDeductions' in o) delete o.settlementDeductions;
                                    if ('settledProfitValue' in o) delete o.settledProfitValue;
                                    o.history = o.history || [];
                                    o.history.push({
                                        time: new Date().toLocaleString('en-GB'),
                                        actor: 'Super Admin',
                                        message: 'সেটেলমেন্ট অডিট লগ ডিলিট করার কারণে প্রফিট নিষ্পত্তি রিসেট করা হয়েছে।'
                                    });

                                    if (window.db) {
                                        orderResetPromises.push(
                                            window.db.collection('bexo_orders').doc(String(o.id)).set(sanitizeForFirestore(o))
                                                .catch(err => console.error(`Error resetting order Doc ${o.id}:`, err))
                                        );
                                    }
                                }
                            });

                            localStorage.setItem('bexo_orders', JSON.stringify(appOrders));
                        }

                        // Wait for all promises
                        await Promise.all([...deletePromises, ...orderResetPromises]);

                        // 3. Clear from local appTransactions
                        appTransactions = appTransactions.filter(t => t.type !== 'Reseller Settlement');
                        localStorage.setItem('bexo_transactions', JSON.stringify(appTransactions));

                        // Refresh UI
                        renderResellerSettlementModule();
                        showToast("সমস্ত সেটেলমেন্ট ও প্রফিট অডিট রেকর্ড সফলভাবে ডিলিট করা হয়েছে!", "success");

                    } catch (error) {
                        console.error("Error deleting settlement logs:", error);
                        showToast("রেকর্ড ডিলিট করতে ত্রুটি ঘটেছে!", "error");
                    }
                };

                window.changeSettlementTab = function(tabName) {
                    window.activeSettlementTab = tabName;
                    window.settlementListSearchKeyword = '';
                    const containerEl = document.getElementById('loadedSettlementOrderContainer');
                    if (containerEl) containerEl.classList.add('hidden');
                    const listsContainer = document.getElementById('settlementListsContainer');
                    if (listsContainer) listsContainer.classList.remove('hidden');
                    renderResellerSettlementModule();
                };

                window.renderActiveTabListHTML = function() {
                    const area = document.getElementById('activeTabListArea');
                    if (!area) return;
                    if (window.activeSettlementTab === 'search') {
                        area.innerHTML = '';
                        return;
                    }
                    const k = window.settlementListSearchKeyword || '';
                    area.innerHTML = window.getTabListHTML(window.activeSettlementTab, k);
                };

                window.hideSettlementDetails = function() {
                    const containerEl = document.getElementById('loadedSettlementOrderContainer');
                    if (containerEl) containerEl.classList.add('hidden');
                    const listEl = document.getElementById('settlementListsContainer');
                    if (listEl) listEl.classList.remove('hidden');
                    const searchInput = document.getElementById('settlementSearchTokenInput');
                    if (searchInput) searchInput.value = '';
                };

                window.loadOrderToSettlement = function(orderId) {
                    const order = (appOrders || []).find(o => String(o.id) === String(orderId));
                    if (!order) return;
                    const token = order.paymentCode || order.secretToken || order.id;

                    const searchInput = document.getElementById('settlementSearchTokenInput');
                    if (searchInput) {
                        searchInput.value = token;
                    }
                    
                    window.activeSettlementTab = 'search';
                    const listEl = document.getElementById('settlementListsContainer');
                    if (listEl) listEl.classList.add('hidden');
                    
                    const searchCard = document.getElementById('highSecuritySearchCard');
                    if (searchCard) searchCard.classList.remove('hidden');

                    searchSettlementToken();
                };

                window.getTabListHTML = function(tabName, keywordFilter) {
                    let list = [];
                    if (tabName === 'due') {
                        list = (appOrders || []).filter(o => 
                            (o.paymentCode || o.secretToken) &&
                            (o.status === 'Delivery Completed' || o.status === 'Completed' || o.status === 'Delivered') && 
                            !o.isProfitDistributed
                        );
                    } else if (tabName === 'pending_delivery') {
                        list = (appOrders || []).filter(o => 
                            (o.paymentCode || o.secretToken) &&
                            o.status !== 'Delivery Completed' && 
                            o.status !== 'Completed' && 
                            o.status !== 'Delivered' && 
                            o.status !== 'Canceled' && 
                            !o.isProfitDistributed
                        );
                    } else if (tabName === 'paid') {
                        list = (appOrders || []).filter(o => 
                            (o.paymentCode || o.secretToken) &&
                            !!o.isProfitDistributed
                        );
                    }

                    if (keywordFilter) {
                        const k = keywordFilter.trim().toLowerCase();
                        list = list.filter(o => {
                            const user = (appUsers || []).find(u => u.profileId === o.profileId);
                            const shop = o.resellerShopName || (user ? user.shopName : '') || '';
                            const resName = o.resellerName || (user ? user.fullName : '') || '';
                            return (
                                (o.orderNo && String(o.orderNo).toLowerCase().includes(k)) ||
                                (o.paymentCode && o.paymentCode.toLowerCase().includes(k)) ||
                                (o.secretToken && o.secretToken.toLowerCase().includes(k)) ||
                                (shop.toLowerCase().includes(k)) ||
                                (resName.toLowerCase().includes(k)) ||
                                (String(o.id).toLowerCase().includes(k))
                            );
                        });
                    }

                    if (list.length === 0) {
                        return `
                            <div class="p-16 text-center bg-white rounded-[2rem] border border-slate-100 shadow-sm space-y-3">
                                <div class="w-12 h-12 bg-slate-50 text-slate-300 rounded-full flex items-center justify-center text-lg mx-auto">
                                    <i class="fas fa-folder-open"></i>
                                </div>
                                <p class="text-xs text-slate-400 font-bold">এই তালিকায় বর্তমানে কোনো অর্ডার পাওয়া যায়নি।</p>
                            </div>
                        `;
                    }

                    return `
                        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                            ${list.map(o => {
                                const user = (appUsers || []).find(u => u.profileId === o.profileId);
                                const resellerName = o.resellerName || (user ? user.fullName : 'অজ্ঞাত রেসেলার');
                                const shopName = o.resellerShopName || (user ? user.shopName : 'Official Website');
                                
                                const sellingPrice = Number(o.totalSellingPrice || o.total || 0);
                                const basePrice = Number(o.totalBasePrice || 0);
                                const courierCharge = Number(o.shipping ? o.shipping.courierCharge : (o.deliveryCharge || 0));
                                const suggestedProfit = o.settledProfitValue || Math.max(0, sellingPrice - basePrice - courierCharge);

                                const tokenDisplay = o.paymentCode ? `
                                    <span class="px-2.5 py-1 bg-[#ff6b21]/10 border border-[#ff6b21]/25 text-[#ff6b21] rounded-lg font-black text-[10px]">
                                        <i class="fas fa-ticket-alt mr-1"></i> কোড: ${o.paymentCode}
                                    </span>
                                ` : `
                                    <span class="px-2.5 py-1 bg-amber-50 border border-amber-100 text-amber-600 rounded-lg text-[10px] font-bold">
                                        <i class="fas fa-barcode mr-1"></i> টোকেন: ${o.secretToken || 'N/A'}
                                    </span>
                                `;

                                const btnHTML = tabName === 'due' ? `
                                    <button onclick="loadOrderToSettlement('${o.id}')" class="px-4 py-2 bg-[#ff6b21] hover:bg-slate-900 border-0 text-white rounded-xl text-[10px] font-black uppercase tracking-wider shadow-md transition-all flex items-center justify-center gap-1.5 cursor-pointer">
                                        <i class="fas fa-cash-register"></i> হিসাব নিষ্পত্তি
                                    </button>
                                ` : tabName === 'pending_delivery' ? `
                                    <button onclick="loadOrderToSettlement('${o.id}')" class="px-4 py-2 bg-slate-800 hover:bg-[#ff6b21] border-0 text-white rounded-xl text-[10px] font-black uppercase tracking-wider transition-all flex items-center justify-center gap-1.5 cursor-pointer">
                                        <i class="fas fa-shipping-fast"></i> কুরিয়ার ও পেমেন্ট এডিট
                                    </button>
                                ` : `
                                    <button onclick="loadOrderToSettlement('${o.id}')" class="px-4 py-2 bg-indigo-650 bg-[#ff6b21] hover:bg-[#e05a1b] border-0 text-white rounded-xl text-[10px] font-black uppercase tracking-wider shadow-md transition-all flex items-center justify-center gap-1.5 cursor-pointer">
                                        <i class="fas fa-file-invoice-dollar"></i> রিসিট ও অডিট
                                    </button>
                                `;

                                return `
                                    <div class="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-md hover:border-slate-200/60 transition-all flex flex-col justify-between space-y-4">
                                        <div class="flex items-start justify-between gap-2">
                                            <div class="space-y-1">
                                                <div class="flex items-center gap-2">
                                                    <span class="text-xs font-black text-slate-800">#${o.orderNo || o.id}</span>
                                                    <span class="px-2 py-0.5 bg-slate-100 rounded-md text-[9px] font-bold text-slate-500">${o.status}</span>
                                                </div>
                                                <p class="text-[10px] text-slate-400 font-bold">${o.date || 'unknown date'}</p>
                                            </div>
                                            <div class="text-right">
                                                <span class="text-[10px] font-bold text-slate-400 uppercase">Reseller</span>
                                                <p class="text-xs font-black text-slate-700 leading-tight">${resellerName}</p>
                                                <p class="text-[9px] text-[#ff6b21] font-bold">${shopName}</p>
                                            </div>
                                        </div>

                                        <div class="p-3 bg-slate-50/50 rounded-2xl grid grid-cols-2 gap-4 text-xs font-bold text-slate-600">
                                            <div>
                                                <p class="text-[9px] text-slate-400 uppercase">মোট বিক্রয় মূল্য</p>
                                                <p class="text-slate-800 font-black">৳ ${sellingPrice.toLocaleString()}</p>
                                            </div>
                                            <div>
                                                <p class="text-[9px] text-slate-400 uppercase">পেমেন্ট লভ্যাংশ (Profit)</p>
                                                <p class="text-emerald-600 font-black font-mono">৳ ${suggestedProfit.toLocaleString()}</p>
                                            </div>
                                        </div>

                                        <div class="flex items-center justify-between gap-2 pt-2 border-t border-slate-50/70">
                                            <div>
                                                ${tokenDisplay}
                                            </div>
                                            ${btnHTML}
                                        </div>
                                    </div>
                                `;
                            }).join('')}
                        </div>
                    `;
                };

               function verifySuperAdminPin() {
                   const pinInput = document.getElementById('superAdminPinInput');
                   if (!pinInput) return;

                   const enteredPin = pinInput.value.trim();
                   if (enteredPin === 'super123') {
                       sessionStorage.setItem('bexo_super_admin_verified', 'true');
                       showToast("সুপার অ্যাডমিন সিকিউরিটি অ্যাক্সেস আনলকড!", "success");
                       renderResellerSettlementModule();
                   } else {
                       showToast("ভুল সিকিউরিটি পিন নম্বর! আবার চেষ্টা করুন।", "error");
                       pinInput.value = '';
                       pinInput.focus();
                   }
               }

               // 4. Reset Session and Lock again
               function resetSuperAdminVerification() {
                   sessionStorage.removeItem('bexo_super_admin_verified');
                   showToast("সুপার অ্যাডমিন সেশন লক করা হয়েছে।", "info");
                   renderResellerSettlementModule();
               }

               // 5. Build recent orders token helper list
               function getRecentSecretTokensListHTML() {
                   const orders = (appOrders || []).slice(0, 10);
                   if (orders.length === 0) {
                       return `<p class="text-xs text-slate-300 font-bold text-center py-4">বর্তমানে কোনো অর্ডার পাওয়া যায়নি</p>`;
                   }

                   return orders.map(o => {
                       const statusColors = {
                           'Pending': 'bg-amber-50 text-amber-600 border-amber-100',
                           'Delivery Completed': 'bg-emerald-50 text-emerald-600 border-emerald-100',
                           'Completed': 'bg-emerald-50 text-emerald-600 border-emerald-100',
                           'Canceled': 'bg-rose-50 text-rose-600 border-rose-100'
                       };
                       const stClass = statusColors[o.status] || 'bg-slate-50 text-slate-600 border-slate-100';

                       return `
                           <div onclick="document.getElementById('settlementSearchTokenInput').value='${o.secretToken}'; searchSettlementToken();" 
                                class="p-3 bg-slate-50/50 hover:bg-orange-50/30 rounded-xl border border-slate-100 cursor-pointer transition-all flex items-center justify-between group">
                               <div class="space-y-1">
                                   <p class="text-[11px] font-black text-slate-700 tracking-wider flex items-center gap-1 group-hover:text-orange-600 transition-colors">
                                       <i class="fas fa-barcode"></i> ${o.secretToken || 'N/A'}
                                   </p>
                                   <div class="flex items-center gap-2">
                                       <span class="text-[9px] text-slate-400 font-bold">আইডি: #${o.orderNo || o.id}</span>
                                   </div>
                               </div>
                               <span class="px-2 py-0.5 border text-[8px] font-black rounded-lg ${stClass}">${o.status}</span>
                           </div>
                       `;
                   }).join('');
               }

               // 6. Search for Token & Load screen
               function searchSettlementToken() {
                   const inputEl = document.getElementById('settlementSearchTokenInput');
                   const errorEl = document.getElementById('settlementSearchError');
                   const errorTextEl = document.getElementById('settlementSearchErrorText');
                   const containerEl = document.getElementById('loadedSettlementOrderContainer');

                   if (!inputEl) return;
                   const query = inputEl.value.trim().toUpperCase();

                   if (!query) {
                       errorTextEl.innerText = "দয়া করে একটি সিক্রেট টোকেন নম্বর অথবা অর্ডার আইডি লিখুন!";
                       errorEl.classList.remove('hidden');
                       containerEl.classList.add('hidden');
                       return;
                   }

                   errorEl.classList.add('hidden');

                   // Perform search against secretToken or orderNo exactly
                   const order = (appOrders || []).find(o => 
                       (o.secretToken && o.secretToken.trim().toUpperCase() === query) ||
                       (o.orderNo && o.orderNo.trim().toUpperCase() === query) ||
                       (String(o.id) === query)
                   );

                   if (!order) {
                       errorTextEl.innerText = "দুঃখিত, এই সিক্রেট টোকেন নম্বরের কোনো অর্ডার পাওয়া যায়নি!";
                       errorEl.classList.remove('hidden');
                       containerEl.classList.add('hidden');
                       return;
                   }

                   // Display Loaded Order Card and Calculation details
                   containerEl.classList.remove('hidden');
                   renderLoadedSettlementDetailsCard(order);
               }

               // 7. Render Loaded settlement details (delivery check & calculator)
               function renderLoadedSettlementDetailsCard(order) {
                   const container = document.getElementById('loadedSettlementOrderContainer');
                   if (!container) return;

                   // Resolve Reseller User Info
                   const reseller = (appUsers || []).find(u => u.profileId === order.profileId) || {
                       fullName: 'অজ্ঞাত রেসেলার',
                       phone: order.resellerPhone || 'N/A',
                       shopName: order.resellerShopName || 'Official Website',
                       rechargeBalance: 0
                   };

                   const isDelivered = (order.status === 'Delivery Completed' || order.status === 'Completed' || order.status === 'Delivered');
                   const isSettled = !!order.isProfitDistributed;

                   // Base financial calculations from order items
                   const sellingPrice = Number(order.totalSellingPrice || order.total || 0);
                   const basePrice = Number(order.totalBasePrice || 0);
                   const courierCharge = Number(order.shipping ? order.shipping.courierCharge : (order.deliveryCharge || 0));

                   // Calculate default suggested net profit
                   const suggestedProfit = Math.max(0, sellingPrice - basePrice - courierCharge);

                   container.innerHTML = `
                       <div class="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl shadow-slate-100/30 overflow-hidden space-y-6 animate-fade-in">
                           <!-- Card Header block: Order metadata -->
                           <div class="p-6 md:p-8 bg-slate-50 border-b border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-4">
                               <div class="space-y-1">
                                   <div class="flex items-center gap-3">
                                       <span class="px-3 py-1 bg-slate-900 text-white rounded-xl text-[10px] font-black tracking-widest uppercase">অর্ডার #${order.orderNo || order.id}</span>
                                       <span class="px-3 py-1 bg-orange-50 text-orange-600 rounded-xl text-[10px] font-black tracking-widest uppercase border border-orange-100 flex items-center gap-1">
                                           <i class="fas fa-barcode"></i> ${order.secretToken || 'N/A'}
                                       </span>
                                   </div>
                                   <p class="text-slate-400 text-xs font-bold mt-1">তারিখ: ${order.date || order.history && order.history[0] && order.history[0].time || 'N/A'}</p>
                               </div>
                               <!-- Reseller Details Block -->
                               <div class="flex items-center gap-3">
                                   <div class="text-right">
                                       <p class="text-xs font-black text-slate-800">${reseller.fullName}</p>
                                       <p class="text-[10px] text-slate-400 font-bold">${reseller.shopName || 'ব্যক্তিগত ড্রপশিপার'}</p>
                                   </div>
                                   <div class="w-10 h-10 bg-indigo-50 border border-indigo-100 text-indigo-600 rounded-full flex items-center justify-center">
                                       <i class="fas fa-store"></i>
                                   </div>
                               </div>
                           </div>

                           <div class="p-6 md:p-8 space-y-8">
                               <!-- Order Items summary -->
                               <div class="space-y-4">
                                   <h4 class="text-xs font-black uppercase text-slate-400 tracking-wider">প্রোডাক্ট বিবরণী</h4>
                                   <div class="divide-y divide-slate-50 border border-slate-100 rounded-2xl p-4 bg-slate-50/50">
                                       ${(order.items || []).map(item => `
                                           <div class="flex items-center justify-between py-2 gap-4">
                                               <div class="flex items-center gap-3">
                                                   <img src="${item.image}" class="w-10 h-10 object-contain rounded-lg border border-slate-200 bg-white p-0.5" referrerPolicy="no-referrer">
                                                   <div>
                                                       <p class="text-xs font-black text-slate-700">${item.title}</p>
                                                       <p class="text-[10px] text-slate-400 font-bold">Qty: ${item.qty} | সাইজ: ${item.size || 'N/A'}</p>
                                                   </div>
                                               </div>
                                               <div class="text-right">
                                                   <p class="text-xs font-black text-slate-700">৳ ${item.sellingPrice}</p>
                                                   <p class="text-[9px] text-slate-400 font-bold">কিনার মূল্য: ৳${item.basePrice}</p>
                                               </div>
                                           </div>
                                       `).join('')}
                                   </div>
                               </div>

                               <!-- If NOT delivered/completed, offer delivery confirmation button -->
                               ${!isDelivered ? `
                                   <div class="p-6 bg-amber-50 rounded-3xl border border-amber-100 space-y-4">
                                       <div class="flex items-start gap-3 text-amber-800">
                                           <i class="fas fa-exclamation-triangle text-xl mt-1"></i>
                                           <div>
                                               <p class="text-xs font-black">অর্ডার স্ট্যাটাস বর্তমানে নিশ্চিতভাবে ডেলিভারি করা হয়নি!</p>
                                               <p class="text-[10px] text-amber-600 font-bold mt-0.5">এই অর্ডারের বর্তমান অবস্থা হল: "<span class="font-extrabold">${order.status}</span>"। হিসাব নিষ্পত্তির পূর্বে কুরিয়ারে ডেলিভারি সম্পন্ন হতে হবে।</p>
                                           </div>
                                       </div>
                                       <button onclick="settleConfirmDelivery('${order.id}')" 
                                               class="w-full sm:w-auto px-6 py-3.5 bg-amber-600 hover:bg-emerald-600 transition-all text-white font-black text-xs uppercase tracking-widest rounded-xl flex items-center justify-center gap-2 cursor-pointer shadow-md">
                                           <i class="fas fa-shipping-fast"></i> ডেলিভারি নিশ্চিত করুন (Confirm Delivery)
                                       </button>
                                   </div>
                               ` : `
                                   <div class="p-4 bg-emerald-50 text-emerald-800 rounded-2xl border border-emerald-100 flex items-center gap-2 text-xs font-bold animate-fade-in animate-pulse">
                                       <i class="fas fa-check-circle"></i>
                                       <span>ডেলিভারি স্ট্যাটাস ভেরিফাইড! আর্থিক হিসাব গণনা নিচে সক্রিয় রয়েছে।</span>
                                   </div>
                               `}

                               <!-- Financial Interactive Calculation Area -->
                               <div class="pt-4 border-t border-slate-100 space-y-6">
                                   <h4 class="text-xs font-black uppercase text-slate-400 tracking-wider">ফিন্যান্সিয়াল ক্যালকুলেশন ও হিসাব নিষ্পতি</h4>
                                   
                                   <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                                       <!-- Unit values display (ReadOnly) -->
                                       <div class="p-4 bg-slate-50 border border-slate-100 rounded-2xl">
                                           <p class="text-[10px] font-black uppercase text-slate-400 tracking-wider">মোট বিক্রয় মূল্য (A)</p>
                                           <p class="text-lg font-black text-slate-800 mt-1">৳ <span id="calcSellingPrice">${sellingPrice}</span></p>
                                       </div>
                                       <div class="p-4 bg-slate-50 border border-slate-100 rounded-2xl">
                                           <p class="text-[10px] font-black uppercase text-slate-400 tracking-wider">মোট কিনার মূল্য (B)</p>
                                           <p class="text-lg font-black text-slate-800 mt-1">৳ <span id="calcBasePrice">${basePrice}</span></p>
                                       </div>
                                       
                                       <!-- Delivery Charge input -->
                                       <div class="p-4 bg-white border border-slate-200 focus-within:border-orange-500 rounded-2xl transition-all">
                                           <p class="text-[10px] font-black uppercase text-slate-400 tracking-wider">কুরিয়ার / ডেলিভারি চার্জ (C)</p>
                                           <input type="number" id="settleDeliveryChargeInput" 
                                                  class="w-full bg-transparent border-0 font-black text-lg text-slate-800 mt-1 outline-none focus:ring-0 p-0" 
                                                  value="${courierCharge}" 
                                                  oninput="updateSettleCalculation('${order.id}')">
                                       </div>
                                       <!-- Other deductions input -->
                                       <div class="p-4 bg-white border border-slate-200 focus-within:border-rose-500 rounded-2xl transition-all">
                                           <div class="flex items-center justify-between">
                                               <p class="text-[10px] font-black uppercase text-slate-400 tracking-wider">অন্যান্য কর্তন (D)</p>
                                               <span class="text-[8px] text-slate-400 font-extrabold italic bg-slate-100 p-0.5 rounded">প্যাকিং/ক্ষতি/রিটার্ন</span>
                                           </div>
                                           <input type="number" id="settleDeductionsInput" 
                                                  class="w-full bg-transparent border-0 font-black text-lg text-rose-600 mt-1 outline-none focus:ring-0 p-0" 
                                                  value="0" 
                                                  oninput="updateSettleCalculation('${order.id}')">
                                       </div>
                                   </div>

                                   <!-- Realtime Net Profit Result Banner -->
                                   <div class="p-6 bg-slate-900 text-white rounded-3xl flex flex-col sm:flex-row items-center justify-between gap-6 shadow-xl shadow-slate-900/10">
                                       <div class="space-y-1 text-left">
                                           <h3 class="text-base font-black tracking-tight text-orange-400 uppercase tracking-widest flex items-center gap-2">
                                               <i class="fas fa-coins text-lg"></i> হিসাব নিষ্পত্তির নেট লভ্যাংশ
                                           </h3>
                                           <p class="text-[11px] text-slate-400 font-bold leading-relaxed">
                                               সূূত্র: লভ্যাংশ = বিক্রয় মূল্য - কিনার মূল্য - ডেলিভারি চার্জ - অন্যান্য কর্তন
                                           </p>
                                       </div>
                                       <div class="text-center sm:text-right">
                                           <p class="text-[10px] font-black text-slate-400 uppercase tracking-widest">রেসেলার ওয়ালেট ব্যালেন্সে যোগ হবে</p>
                                           <h2 class="text-3xl font-black text-emerald-400 mt-1">৳ <span id="settleProfitDisplay">${suggestedProfit}</span></h2>
                                       </div>
                                   </div>

                                   <!-- Settle Payment Action with State Guard -->
                                   <div class="flex flex-col sm:flex-row gap-4 items-center justify-between border-t border-slate-100 pt-6">
                                       <div class="flex items-center gap-3">
                                           <div class="w-10 h-10 bg-slate-100 text-slate-700 rounded-full flex items-center justify-center">
                                               <i class="fas fa-wallet"></i>
                                           </div>
                                           <div class="text-left">
                                               <p class="text-xs font-black text-slate-700">রেসেলার ব্যালেন্স পকেট</p>
                                               <p class="text-[10px] text-slate-400 font-bold">বর্তমান ওয়ালেট ব্যালেন্স: ৳${reseller.rechargeBalance || 0}</p>
                                           </div>
                                       </div>
                                       
                                       <!-- Settle Payment Button -->
                                       ${isSettled ? `
                                           <div class="flex items-center gap-2 text-rose-600 bg-rose-50 border border-rose-100 px-6 py-3.5 rounded-2xl text-xs font-black uppercase tracking-widest">
                                               <i class="fas fa-check-double text-sm"></i>
                                               <span>ইতিমধ্যে প্রফিট বিতরণ করা হয়েছে!</span>
                                           </div>
                                       ` : `
                                           <button id="settlePaymentActionButton" 
                                                   onclick="executeSettlePayment('${order.id}')" 
                                                   ${!isDelivered ? 'disabled class="px-8 py-4 bg-slate-200 text-slate-400 rounded-2xl text-xs font-black uppercase tracking-widest cursor-not-allowed"' : 'class="px-8 py-4 bg-orange-600 hover:bg-emerald-600 text-white rounded-2xl text-xs font-black uppercase tracking-widest transition-all cursor-pointer shadow-lg shadow-orange-600/10 flex items-center gap-2"'} >
                                               <i class="fas fa-hand-holding-usd"></i> পেমেন্ট সেটেলমেন্ট নিশ্চিত করুন
                                           </button>
                                       `}
                                   </div>
                               </div>
                           </div>
                       </div>
                   `;
               }

               // 8. Settle: Confirm Delivery handler
               function settleConfirmDelivery(orderId) {
                   try {
                       updateOrderStatus(orderId, 'Delivery Completed', 'Admin');
                       // Re-load the details screen after updating
                       const idx = appOrders.findIndex(o => String(o.id) === String(orderId));
                       if (idx > -1) {
                           showToast("অর্ডার ডেলিভারি নিশ্চিত করা হয়েছে।", "success");
                           renderLoadedSettlementDetailsCard(appOrders[idx]);
                       }
                   } catch (e) {
                       console.error("Delivery status shift error:", e);
                       showToast("ডেলিভারি স্থিতি পরিবর্তন ব্যর্থ হয়েছে।", "error");
                   }
               }

               // 9. Interactive update change listeners
               function updateSettleCalculation(orderId) {
                   const order = (appOrders || []).find(o => String(o.id) === String(orderId));
                   if (!order) return;

                   const sellingPrice = Number(order.totalSellingPrice || order.total || 0);
                   const basePrice = Number(order.totalBasePrice || 0);

                   const deliveryInput = document.getElementById('settleDeliveryChargeInput');
                   const deductionsInput = document.getElementById('settleDeductionsInput');
                   const profitDisplay = document.getElementById('settleProfitDisplay');

                   if (!deliveryInput || !deductionsInput || !profitDisplay) return;

                   const courierCharge = Number(deliveryInput.value) || 0;
                   const deductions = Number(deductionsInput.value) || 0;

                   // Formula: Net Profit = Selling Price - Base - Courier - Deductions
                   const computedProfit = Math.max(0, sellingPrice - basePrice - courierCharge - deductions);

                   // Realtime Update Display with green colors
                   profitDisplay.innerText = computedProfit.toLocaleString();

                   // Guard button state from negative profits if desired (we just computed)
                   const actionBtn = document.getElementById('settlePaymentActionButton');
                   if (actionBtn) {
                       if (computedProfit <= 0) {
                           actionBtn.classList.add('bg-slate-300', 'text-slate-500');
                           actionBtn.classList.remove('bg-orange-600', 'hover:bg-emerald-600');
                       } else {
                           actionBtn.classList.remove('bg-slate-300', 'text-slate-500');
                           actionBtn.classList.add('bg-orange-600', 'hover:bg-emerald-600');
                       }
                   }
               }

               // 10. Settle Payment implementation with ACID Transaction Integrity
               async function executeSettlePayment(orderId) {
                   const orderIdx = appOrders.findIndex(o => String(o.id) === String(orderId));
                   if (orderIdx === -1) {
                       showToast("অর্ডার পাওয়া যায়নি!", "error");
                       return;
                   }

                   const order = appOrders[orderIdx];
                   if (order.isProfitDistributed) {
                       showToast("এই অর্ডারের প্রফিট ইতিপূর্বে সেটেল করা হয়েছে!", "error");
                       return;
                   }

                   // Get interactive parameters values
                   const deliveryInput = document.getElementById('settleDeliveryChargeInput');
                   const deductionsInput = document.getElementById('settleDeductionsInput');

                   const courierCharge = deliveryInput ? Number(deliveryInput.value) : Number(order.shipping ? order.shipping.courierCharge : 0);
                   const deductions = deductionsInput ? Number(deductionsInput.value) : 0;

                   const sellingPrice = Number(order.totalSellingPrice || order.total || 0);
                   const basePrice = Number(order.totalBasePrice || 0);

                   // Compute profit
                   const computedProfit = Math.max(0, sellingPrice - basePrice - courierCharge - deductions);
                   const resellerProfileId = order.profileId;

                   if (!resellerProfileId) {
                       showToast("ত্রুটি: রেসেলারের প্রোফাইল আইডি পাওয়া যায়নি!", "error");
                       return;
                   }

                   // Confirm Action dialog alert style (Using simple premium UI instead of blocky alert)
                   if (!confirm(`আপনি কি এই অর্ডারের জন্য ৳${computedProfit} প্রফিট নিষ্পত্তি নিশ্চিত করতে চান? এটি রেসেলার ওয়ালেটে সরাসরি যুক্ত করা হবে।`)) {
                       return;
                   }

                   // Update Status: Setup Loader
                   const actionBtn = document.getElementById('settlePaymentActionButton');
                   if (actionBtn) {
                       actionBtn.disabled = true;
                       actionBtn.innerHTML = `<i class="fas fa-spinner animate-spin"></i> প্রসেস হচ্ছে...`;
                   }

                   // Build immutability payloads
                   const settlementTxnId = 'SETTLE-TXN-' + Date.now();
                   const timestamp = new Date().toLocaleString('en-GB');

                   const auditTxnEntry = {
                       id: settlementTxnId,
                       date: timestamp,
                       timestamp: Date.now(),
                       profileId: resellerProfileId,
                       userId: order.resellerPhone || resellerProfileId,
                       orderNo: order.orderNo || order.id,
                       secretToken: order.secretToken || 'N/A',
                       sellingPrice: sellingPrice,
                       basePrice: basePrice,
                       courierCharge: courierCharge,
                       otherDeductions: deductions,
                       netProfit: computedProfit,
                       adminId: 'admin@bexo.com',
                       adminName: 'Super Admin',
                       clientIP: window.adminClientIP || '103.118.42.10',
                       type: 'Reseller Settlement',
                       status: 'Success',
                       details: `Settlement for order #${order.orderNo || order.id} (Deductions: ৳${deductions})`
                   };

                   const userTxEntry = {
                       id: 'TX-PROFIT-' + Date.now(),
                       type: 'Order Profit',
                       details: `Profit from order #${order.orderNo || order.id} (Settle Audit: Net ৳${computedProfit})`,
                       amount: computedProfit,
                       time: timestamp
                   };

                   // Execute ACID Transaction process
                   try {
                       if (window.db) {
                           // Use relational atomicity transaction across Firestore if online!
                           const userDocRef = window.db.collection('bexo_users').doc(String(resellerProfileId));
                           const orderDocRef = window.db.collection('bexo_orders').doc(String(order.id));
                           const txnDocRef = window.db.collection('bexo_transactions').doc(String(settlementTxnId));

                           await window.db.runTransaction(async (transaction) => {
                               // Read active order from inside transactional bounds
                               const orderDoc = await transaction.get(orderDocRef);
                               const orderData = orderDoc.data() || {};
                               if (orderData.isProfitDistributed) {
                                   throw new Error("This order has already been settled in a different session!");
                               }

                               // Perform updates atomically inside transaction
                               // Note: User balance is NO LONGER updated automatically here. 
                               // Funds are only added via manual Profile Payment approval workflow.

                               transaction.update(orderDocRef, {
                                   isProfitDistributed: true,
                                   settlementDeductions: deductions,
                                   settledProfitValue: computedProfit,
                                   status: 'Delivery Completed'
                               });

                               transaction.set(txnDocRef, sanitizeForFirestore(auditTxnEntry));
                           });
                       }

                       // Synchronize status locally
                       // NOTE: User balance update logic removed per strict manual-only workflow rules.

                       // Mark local order object
                       order.isProfitDistributed = true;
                       order.settlementDeductions = deductions;
                       order.settledProfitValue = computedProfit;
                       order.status = 'Delivery Completed';
                       order.history = order.history || [];
                       order.history.push({
                           time: timestamp,
                           actor: 'Super Admin',
                           message: `লভ্যাংশ নিষ্পত্তি করা হয়েছে: ৳${computedProfit} (কর্তন: ৳${deductions})`
                       });
                       saveOrders();

                       // Log globally
                       appTransactions.unshift(auditTxnEntry);
                       saveTransactions();

                       // Render Overlay Success Message
                       if (typeof showSuccessOverlay === 'function') {
                           showSuccessOverlay(
                               "নিষ্পত্তি সম্পূর্ণ!",
                               `৳${computedProfit} নেট প্রফিট সফলভাবে রেসেলার ওয়ালেটে যুক্ত করা হয়েছে। (কর্তন: ৳${deductions})`,
                               "fas fa-check-circle",
                               "text-emerald-500",
                               "bg-slate-950 font-sans"
                           );
                       } else {
                           showToast("সেটেলমেন্ট সফলভাবে সম্পন্ন হয়েছে!", "success");
                       }

                       // Refresh Views
                       renderResellerSettlementModule();

                   } catch (err) {
                       console.error("ACID Settlement Transaction Failed:", err);
                       showToast("হিসাব নিষ্পত্তি সম্পন্ন করা সম্ভব হয়নি: " + err.message, "error");
                       
                       // Reset button loading state
                       if (actionBtn) {
                           actionBtn.disabled = false;
                           actionBtn.innerHTML = `<i class="fas fa-hand-holding-usd"></i> পেমেন্ট সেটেলমেন্ট নিশ্চিত করুন`;
                       }
                   }
               }

               // 11. Render Immutable Audit logs table historical details
               function renderSettlementAuditLogsTable() {
                   const tbody = document.getElementById('settlementLogsTbody');
                   const counter = document.getElementById('settleLogCount');
                   if (!tbody) return;

                   // Filter settlements from appTransactions history log
                   const settlements = appTransactions.filter(t => t.type === 'Reseller Settlement');
                   
                   if (counter) counter.innerText = settlements.length;

                   if (settlements.length === 0) {
                       tbody.innerHTML = `
                           <tr>
                               <td colspan="6" class="p-12 text-center text-slate-300 font-bold whitespace-nowrap">বর্তমানে কোন নিষ্পত্তির রেকর্ড পাওয়া যায়নি।</td>
                           </tr>
                       `;
                       return;
                   }

                   tbody.innerHTML = settlements.map(t => {
                       return `
                           <tr class="hover:bg-slate-50 transition-all">
                               <td class="px-8 py-5">
                                   <p class="font-black text-slate-700 tracking-wider text-left">${t.id}</p>
                                   <p class="text-[10px] text-slate-400 font-semibold mt-0.5 text-left">${t.date}</p>
                               </td>
                               <td class="px-8 py-5">
                                   <p class="font-black text-slate-800 text-left">অর্ডার #${t.orderNo}</p>
                                   <div class="text-left">
                                       <span class="inline-flex items-center gap-1 bg-orange-50 text-orange-600 px-2 py-0.5 rounded text-[9px] font-black mt-1 uppercase border border-orange-100 italic">
                                           <i class="fas fa-barcode"></i> ${t.secretToken || 'N/A'}
                                       </span>
                                   </div>
                               </td>
                               <td class="px-8 py-5">
                                   <p class="font-bold text-slate-700 flex items-center gap-1 text-left">
                                       <i class="fas fa-user-circle text-slate-400"></i> ${t.userId || 'System'}
                                   </p>
                               </td>
                               <td class="px-8 py-5 text-slate-500 font-semibold text-left">
                                   <div class="space-y-0.5 text-[10px] text-left">
                                       <p>বিক্রয়: ৳${t.sellingPrice}</p>
                                       <p>কেনার: ৳${t.basePrice}</p>
                                       <p>ডেলিভারি: ৳${t.courierCharge}</p>
                                       <p class="text-rose-600 font-black">কর্তন: ৳${t.otherDeductions || 0}</p>
                                   </div>
                               </td>
                               <td class="px-8 py-5 font-black text-emerald-600 font-mono text-sm text-left">
                                   ৳ ${(Number(t.netProfit) || 0).toLocaleString()}
                               </td>
                               <td class="px-8 py-5 text-right font-semibold text-slate-400">
                                   <p class="text-[10px] text-slate-700 font-black flex items-center justify-end gap-1">
                                       <i class="fas fa-user-shield text-indigo-500"></i> ${t.adminName || 'Admin'}
                                   </p>
                                   <p class="text-[9px] font-mono mt-0.5">${t.clientIP || '127.0.0.1'}</p>
                               </td>
                           </tr>
                       `;
                    }).join('');
                }
